usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Batches.New(
		context.TODO(),
		openai.BatchNewParams{
			InputFileID: "string",
			Endpoint: openai.BatchesCreateRequestEndpointV1Responses,
			CompletionWindow: "24h",
			Metadata: map[string]string{"key": "string"},
			OutputExpiresAfter: openai.BatchFileExpirationAfter{Anchor: "created_at", Seconds: 1},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
